development.solution_text:
[tikz]
\begin{tikzpicture}[scale=0.9]
\coordinate (O) at (0,0);
\coordinate (A) at (0:2.5);
\coordinate (B) at (100:2.5);
\draw (O) -- (A) node[midway,below] {$7\text{ m}$};
\draw (O) -- (B);
\draw[very thick] (100:2.5) arc[start angle=100,end angle=360,radius=2.5];
